import type { CSSProperties } from "react";
import { ARABIC, LATIN, MARK } from "@/components/brand/wordmark-paths";

/**
 * Drawings for the brand book. Every number here comes from the mark's own
 * geometry (src/components/brand/wordmark-paths.ts, generated by
 * scripts/brand-assets.mts), so the construction drawing can't drift from the logo.
 */

export const INK = "#141414";
export const BONE = "#f2f0eb";
export const SIGNAL = "#f04a23";
const STONE_600 = "#67635b";
const STONE_300 = "#cdc8bd";
const STONE_200 = "#e2ded5";

const fmt = (n: number) => String(Math.round(n * 100) / 100);
const GAP = MARK.bars[1]!.y + MARK.h - MARK.bars[0]!.y; // negative: rows go up
const ROW_GAP = Math.abs(GAP);
const STEP = MARK.bars[1]!.x - MARK.bars[0]!.x;

function MarkShapes({ fg = INK, dot = SIGNAL }: { fg?: string; dot?: string }) {
  return (
    <>
      {MARK.bars.map((b) => (
        <rect key={b.y} x={b.x} y={b.y} width={b.w} height={MARK.h} rx={MARK.h / 2} fill={fg} />
      ))}
      <circle cx={MARK.dot.cx} cy={MARK.dot.cy} r={MARK.dot.r} fill={dot} />
    </>
  );
}

/** A 64-unit grid: a line every 4 units, stronger every 16. */
function Grid({ minor, major, size = 64 }: { minor: string; major: string; size?: number }) {
  const lines = Array.from({ length: size / 4 + 1 }, (_, i) => i * 4);
  return (
    <g>
      {lines.map((v) => (
        <g key={v} stroke={v % 16 === 0 ? major : minor} strokeWidth={v % 16 === 0 ? 0.16 : 0.1}>
          <line x1={v} y1={0} x2={v} y2={size} />
          <line x1={0} y1={v} x2={size} y2={v} />
        </g>
      ))}
    </g>
  );
}

/**
 * The tangent through the rounded band ends: the legs of the A. Returns the
 * apex and the foot of the left leg (the right one mirrors it).
 */
function aLeg() {
  const [b0, b1] = MARK.bars as [{ x: number; y: number; w: number }, { x: number; y: number; w: number }];
  const r = MARK.h / 2;
  const c0 = { x: b0.x + r, y: b0.y + r };
  const c1 = { x: b1.x + r, y: b1.y + r };
  const len = Math.hypot(c1.x - c0.x, c1.y - c0.y);
  const n = { x: (c1.y - c0.y) / len, y: -(c1.x - c0.x) / len }; // outward normal, to the left
  const p = { x: c0.x + n.x * r, y: c0.y + n.y * r };
  const slope = (c1.x - c0.x) / (c1.y - c0.y); // dx per dy
  const xAt = (y: number) => p.x + (y - p.y) * slope;
  const apexY = p.y + (32 - p.x) / slope;
  return { apex: { x: 32, y: apexY }, foot: { x: xAt(63), y: 63 } };
}

/** The mark drawn on its grid, with every measurement. */
export function MarkConstruction({ labels }: { labels: { units: string; row: string; gap: string; step: string; dot: string; radius: string } }) {
  const { apex, foot } = aLeg();
  const [b0, b1] = MARK.bars as [{ x: number; y: number; w: number }, { x: number; y: number; w: number }];
  const r = MARK.h / 2;
  const t = { fontSize: 2.5, fill: STONE_600, fontFamily: "var(--font-sans)" } as const;
  const dim = { stroke: STONE_600, strokeWidth: 0.16 } as const;
  return (
    <svg viewBox="-17 -11 100 86" className="h-auto w-full" role="img" aria-label={labels.units} direction="ltr">
      <Grid minor={STONE_200} major={STONE_300} />
      <rect x={0} y={0} width={64} height={64} fill="none" stroke={STONE_300} strokeWidth={0.22} />
      {/* The legs of the A, tangent to every band end. */}
      <g stroke={SIGNAL} strokeWidth={0.22} strokeDasharray="1 0.8">
        <line x1={apex.x} y1={apex.y} x2={foot.x} y2={foot.y} />
        <line x1={apex.x} y1={apex.y} x2={64 - foot.x} y2={foot.y} />
      </g>
      <MarkShapes />
      {MARK.bars.map((b) => (
        <text key={b.y} x={32} y={b.y + r + 1.05} textAnchor="middle" fontSize={3} fontWeight={600} fill={BONE} fontFamily="var(--font-sans)" className="tabular">
          {fmt(b.w)}
        </text>
      ))}
      {/* 64 across the top */}
      <g {...dim}>
        <line x1={0} y1={-4} x2={64} y2={-4} />
        <line x1={0} y1={-5.2} x2={0} y2={-2.8} />
        <line x1={64} y1={-5.2} x2={64} y2={-2.8} />
      </g>
      <text x={32} y={-5.8} textAnchor="middle" {...t}>{labels.units}</text>
      {/* Row height and gap down the left */}
      <g {...dim}>
        <line x1={-4} y1={b0.y} x2={-4} y2={b0.y + MARK.h} />
        <line x1={-5.2} y1={b0.y} x2={-2.8} y2={b0.y} />
        <line x1={-5.2} y1={b0.y + MARK.h} x2={-2.8} y2={b0.y + MARK.h} />
        <line x1={-4} y1={b1.y + MARK.h} x2={-4} y2={b0.y} strokeDasharray="0.5 0.5" />
        <line x1={-5.2} y1={b1.y + MARK.h} x2={-2.8} y2={b1.y + MARK.h} />
      </g>
      <text x={-6} y={b0.y + r + 0.9} textAnchor="end" {...t}>{labels.row}</text>
      <text x={-6} y={b0.y - ROW_GAP / 2 + 0.9} textAnchor="end" {...t}>{labels.gap}</text>
      {/* The step in from one band to the next */}
      <g {...dim}>
        <line x1={b0.x} y1={67.5} x2={b1.x} y2={67.5} />
        <line x1={b0.x} y1={66.3} x2={b0.x} y2={68.7} />
        <line x1={b1.x} y1={66.3} x2={b1.x} y2={68.7} />
        <line x1={b0.x} y1={b0.y + MARK.h} x2={b0.x} y2={66.3} strokeDasharray="0.5 0.5" />
        <line x1={b1.x} y1={b1.y + MARK.h} x2={b1.x} y2={66.3} strokeDasharray="0.5 0.5" />
      </g>
      <text x={b0.x + STEP / 2} y={71.6} textAnchor="middle" {...t}>{labels.step}</text>
      {/* The dot */}
      <g {...dim}>
        <line x1={MARK.dot.cx + MARK.dot.r + 1} y1={MARK.dot.cy} x2={48} y2={MARK.dot.cy} />
      </g>
      <text x={49} y={MARK.dot.cy + 0.9} {...t}>{labels.dot}</text>
      {/* Full round ends */}
      <circle cx={b0.x + b0.w - r} cy={b0.y + r} r={r} fill="none" stroke={SIGNAL} strokeWidth={0.22} strokeDasharray="0.8 0.6" />
      <g {...dim}>
        <line x1={b0.x + b0.w - r} y1={b0.y + r} x2={68} y2={b0.y + r} />
      </g>
      <text x={69} y={b0.y + r + 0.9} {...t}>{labels.radius}</text>
    </svg>
  );
}

/** The mark on its grid, large, for the cover. */
export function CoverMark() {
  return (
    <svg viewBox="-8 -8 80 80" className="h-auto w-full" aria-hidden>
      <g transform="translate(-8 -8)">
        {Array.from({ length: 21 }, (_, i) => i * 4).map((v) => (
          <g key={v} stroke={BONE} strokeOpacity={v % 16 === 0 ? 0.12 : 0.05} strokeWidth={0.12}>
            <line x1={v} y1={0} x2={v} y2={80} />
            <line x1={0} y1={v} x2={80} y2={v} />
          </g>
        ))}
      </g>
      <MarkShapes fg={BONE} />
    </svg>
  );
}

/**
 * One skill, measured: the band of plausible levels after each answer,
 * narrowing towards the estimate. Drawn bottom-up, like the mark.
 */
export function NarrowingFigure({ rows, estimate, scale, rtl }: { rows: { label: string; lo: number; hi: number }[]; estimate: { label: string; value: number }; scale: [string, string]; rtl: boolean }) {
  const W = 150;
  const labelW = 44;
  const x0 = labelW + 6;
  const x1 = W - 5;
  const lx = (level: number) => x0 + ((level - 1) / 4) * (x1 - x0);
  const X = (x: number) => (rtl ? W - x : x);
  const h = 10;
  const rowY = (i: number) => 70 - i * 18; // i = 0 is the first answer, at the bottom
  const all = [...rows.map((r) => ({ ...r, dot: false })), { label: estimate.label, lo: estimate.value, hi: estimate.value, dot: true }];
  const text = { fontSize: 5, fill: STONE_600, fontFamily: "var(--font-sans)" } as const;
  // direction="ltr" so text-anchor means the same thing in both languages; Arabic still shapes right to left.
  return (
    <svg viewBox={`0 0 ${W} 98`} className="h-auto w-full" role="img" aria-label={all.map((r) => r.label).join(", ")} direction="ltr">
      {all.map((r, i) => {
        const y = rowY(i);
        const a = X(lx(r.lo));
        const b = X(lx(r.hi));
        return (
          <g key={r.label}>
            <line x1={X(x0)} y1={y} x2={X(x1)} y2={y} stroke={STONE_300} strokeWidth={0.35} />
            {[1, 2, 3, 4, 5].map((l) => (
              <line key={l} x1={X(lx(l))} y1={y - 1.6} x2={X(lx(l))} y2={y + 1.6} stroke={STONE_300} strokeWidth={0.35} />
            ))}
            {r.dot ? (
              <circle cx={a} cy={y} r={h / 2} fill={SIGNAL} />
            ) : (
              <rect x={Math.min(a, b)} y={y - h / 2} width={Math.abs(b - a)} height={h} rx={h / 2} fill={INK} />
            )}
            <text x={rtl ? W : 0} y={y + 1.7} textAnchor={rtl ? "end" : "start"} {...text} fill={r.dot ? INK : STONE_600} fontWeight={r.dot ? 600 : 400}>
              {r.label}
            </text>
          </g>
        );
      })}
      {[1, 2, 3, 4, 5].map((l) => (
        <text key={l} x={X(lx(l))} y={86} textAnchor="middle" {...text} fontSize={4.4} className="tabular">
          {l}
        </text>
      ))}
      <text x={X(x0)} y={94.5} textAnchor={rtl ? "end" : "start"} {...text} fontSize={4}>
        {scale[0]}
      </text>
      <text x={X(x1)} y={94.5} textAnchor={rtl ? "start" : "end"} {...text} fontSize={4}>
        {scale[1]}
      </text>
    </svg>
  );
}

/** Geometry of the bilingual lockup, as scripts/brand-assets.mts draws it (cap-height units). */
export function lockupBox() {
  const H = LATIN.height;
  const mark = H * 1.62;
  const gap = H * 0.42;
  const scale = (H * 1.18) / ARABIC.baseline;
  const width = mark + gap + LATIN.width + gap * 1.6 + ARABIC.width * scale;
  const top = Math.min((H - mark) / 2, H - H * 1.18);
  const bottom = Math.max((H + mark) / 2, H - ARABIC.baseline * scale + ARABIC.height * scale);
  return { H, mark, gap, width, top, bottom, height: bottom - top };
}

/** Clear space: x (the cap height of AALIM) on every side of the lockup. */
export function ClearSpace({ x }: { x: string }) {
  const { H, width, top, height } = lockupBox();
  const pad = H * 0.06; // logo.svg's own hairline of padding
  const vb = { x: -pad, y: top - pad, w: width + pad * 2, h: height + pad * 2 };
  const m = H * 2.2;
  const zone = { x: vb.x - H, y: vb.y - H, w: vb.w + H * 2, h: vb.h + H * 2 };
  const sq = (cx: number, cy: number, key: string) => (
    <g key={key}>
      <rect x={cx - H / 2} y={cy - H / 2} width={H} height={H} fill={SIGNAL} fillOpacity={0.14} stroke={SIGNAL} strokeWidth={H * 0.025} />
      <text x={cx} y={cy + H * 0.16} textAnchor="middle" fontSize={H * 0.42} fill="#b2300c" fontFamily="var(--font-sans)" fontStyle="italic" fontWeight={600}>
        {x}
      </text>
    </g>
  );
  return (
    <svg viewBox={`${zone.x - m} ${zone.y - m * 0.6} ${zone.w + m * 2} ${zone.h + m * 1.2}`} className="h-auto w-full" role="img" aria-label={x} direction="ltr">
      <rect x={zone.x} y={zone.y} width={zone.w} height={zone.h} fill="none" stroke={STONE_600} strokeWidth={H * 0.03} strokeDasharray={`${H * 0.12} ${H * 0.1}`} />
      <rect x={vb.x} y={vb.y} width={vb.w} height={vb.h} fill="none" stroke={STONE_300} strokeWidth={H * 0.02} />
      <image href="/brand/logo.svg" x={vb.x} y={vb.y} width={vb.w} height={vb.h} />
      {sq(zone.x + H / 2, vb.y + vb.h / 2, "l")}
      {sq(zone.x + zone.w - H / 2, vb.y + vb.h / 2, "r")}
      {sq(vb.x + vb.w * 0.36, zone.y + H / 2, "t")}
      {sq(vb.x + vb.w * 0.36, zone.y + zone.h - H / 2, "b")}
    </svg>
  );
}

/** The mark in fixed brand colours (for artboards, which never follow the theme). */
export function Mark({ fg = INK, dot = SIGNAL, bars, className, style }: { fg?: string; dot?: string; bars?: { x: number; y: number; w: number }[]; className?: string; style?: CSSProperties }) {
  return (
    <svg viewBox="0 0 64 64" className={className} style={style} aria-hidden>
      {(bars ?? MARK.bars).map((b) => (
        <rect key={b.y} x={b.x} y={b.y} width={b.w} height={MARK.h} rx={MARK.h / 2} fill={fg} />
      ))}
      <circle cx={MARK.dot.cx} cy={MARK.dot.cy} r={MARK.dot.r} fill={dot} />
    </svg>
  );
}

/** "AALIM" as a drawing (no live text), for colour samples. */
export function WordmarkShape({ fill, className }: { fill: string; className?: string }) {
  return (
    <svg viewBox={`0 0 ${LATIN.width} ${LATIN.height}`} className={className} aria-hidden>
      <path d={LATIN.d} fill={fill} />
    </svg>
  );
}

/** The two wordmarks on their shared baseline, with the guides that set them. */
export function WordmarkGuides({ labels }: { labels: { cap: string; baseline: string; rise: string } }) {
  const H = LATIN.height;
  const scale = (H * 1.18) / ARABIC.baseline;
  const dy = H - ARABIC.baseline * scale;
  const gap = H * 0.34;
  const arX = LATIN.width + gap * 2;
  const width = arX + ARABIC.width * scale;
  const bottom = dy + ARABIC.height * scale;
  const fs = H * 0.13;
  const left = -H * 0.25;
  const right = width + H * 2.1;
  const label = (y: number, text: string, color = STONE_600) => (
    <text x={width + H * 0.3} y={y + fs * 0.35} fontSize={fs} fill={color} fontFamily="var(--font-sans)">
      {text}
    </text>
  );
  return (
    <svg viewBox={`${left} ${dy - H * 0.35} ${right - left} ${bottom - dy + H * 0.6}`} className="h-auto w-full" role="img" aria-label={`${labels.cap}, ${labels.baseline}, ${labels.rise}`} direction="ltr">
      <g strokeWidth={H * 0.012}>
        <line x1={left} y1={0} x2={width + H * 0.2} y2={0} stroke={STONE_300} />
        <line x1={left} y1={H} x2={width + H * 0.2} y2={H} stroke={STONE_300} />
        <line x1={arX - gap * 0.3} y1={dy} x2={width + H * 0.2} y2={dy} stroke={SIGNAL} strokeDasharray={`${H * 0.05} ${H * 0.04}`} />
      </g>
      <path d={LATIN.d} fill={INK} />
      <rect x={LATIN.width + gap * 0.95} y={H * 0.02} width={H * 0.05} height={H * 0.96} fill={INK} opacity={0.22} />
      <g transform={`translate(${arX} ${dy}) scale(${scale})`}>
        <path d={ARABIC.d} fill={INK} />
      </g>
      {label(0, labels.cap)}
      {label(H, labels.baseline)}
      {label(dy - fs * 0.2, labels.rise, "#b2300c")}
    </svg>
  );
}
